2	
3	import (
4		"encoding/json"
5		"errors"
6		"testing"
7		"time"
8	)
9	
10	// campaignDeviceDoc 返回存储文档中指定活动、指定设备的磁盘记录。
11	func campaignDeviceDoc(doc map[string]any, campaignID, deviceID string) map[string]any {
12		for _, d := range campaignDoc(doc, campaignID)["devices"].([]any) {
13			dev := d.(map[string]any)
14			if dev["deviceId"] == deviceID {
15				return dev
16			}
17		}
18		return nil
19	}
20	
21	// setupRollbackCampaign 创建开启回滚的单设备活动并让 d1 在线，返回未关闭的存储。
22	func setupRollbackCampaign(t *testing.T) (*Store, CampaignSpec) {
23		t.Helper()
24		s := setupUpgrade(t, "d1")
25		spec := rbSpec()
26		createCampaign(t, s, spec)
27		bringOnline(t, s, "d1")
28		return s, spec
29	}
30	
31	// closeStore 关闭存储并返回其目录，供改写磁盘记录后验证拒绝打开。
32	func closeStore(t *testing.T, s *Store) string {
33		t.Helper()
34		dir := s.dir
35		if err := s.Close(); err != nil {
36			t.Fatal(err)
37		}
38		return dir
39	}
40	
41	// TestRestoreRollbackTargetRequired 保护开启回滚活动的回滚目标完整性：
42	// 设备已领取下载且尚无下载结果，或已有成功下载结果时，保存记录必须带非空的
43	// 锁定回滚版本；字段缺失与空串按同一种损坏处理。这项要求不因设备进入安装
44	// 阶段或活动已结束而取消。任一设备违反时 Open 必须返回 ErrCorruptStorage，
45	// 整个存储都不能打开、原文件内容保持不变——不能仅删除这台设备或这个活动，
46	// 让其他记录照常进入可用状态。
47	func TestRestoreRollbackTargetRequired(t *testing.T) {
48		// 已领取下载、尚未有下载结果（downloading）时目标丢失。
49		t.Run("downloading without locked target", func(t *testing.T) {
50			s, spec := setupRollbackCampaign(t)
51			if _, err := s.Claim(spec.ID, "d1", upBase); err != nil {
52				t.Fatalf("claim download: %v", err)
53			}
54			if d := findDevice(mustGetCampaign(s, spec.ID), "d1"); d.Status != DeviceDownloading ||
55				d.RollbackTarget != "v1" {
56				t.Fatalf("precondition: %+v", d)
57			}
58			dir := closeStore(t, s)
59			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
60				delete(campaignDeviceDoc(doc, spec.ID, "d1"), "rollbackTarget")
61			})
62			assertReopenCorrupt(t, dir, original)
63		})
64	
65		// 下载成功、等待安装（ready）时目标被置为空串：与字段缺失同样处理。
66		t.Run("ready with empty target", func(t *testing.T) {
67			s, spec := setupRollbackCampaign(t)
68			dl, err := s.Claim(spec.ID, "d1", upBase)
69			if err != nil {
70				t.Fatalf("claim download: %v", err)
71			}
72			if err := s.SubmitResult(OperationResult{
73				CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
74				At: upBase.Add(time.Minute), Success: true,
75			}); err != nil {
76				t.Fatalf("download result: %v", err)
77			}
78			if d := findDevice(mustGetCampaign(s, spec.ID), "d1"); d.Status != DeviceReady {
79				t.Fatalf("precondition: %+v", d)
80			}
81			dir := closeStore(t, s)
82			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
83				campaignDeviceDoc(doc, spec.ID, "d1")["rollbackTarget"] = ""
84			})
85			assertReopenCorrupt(t, dir, original)
86		})
87	
88		// 已领取安装（installing）时目标丢失：进入安装阶段不取消这项要求。
89		t.Run("installing without locked target", func(t *testing.T) {
90			s, spec := setupRollbackCampaign(t)
91			dl, err := s.Claim(spec.ID, "d1", upBase)
92			if err != nil {
93				t.Fatalf("claim download: %v", err)
94			}
95			if err := s.SubmitResult(OperationResult{
96				CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
97				At: upBase.Add(time.Minute), Success: true,
98			}); err != nil {
99				t.Fatalf("download result: %v", err)
100			}
101			if _, err := s.Claim(spec.ID, "d1", upBase.Add(2*time.Minute)); err != nil {
102				t.Fatalf("claim install: %v", err)
103			}
104			if d := findDevice(mustGetCampaign(s, spec.ID), "d1"); d.Status != DeviceInstalling {
105				t.Fatalf("precondition: %+v", d)
106			}
107			dir := closeStore(t, s)
108			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
109				delete(campaignDeviceDoc(doc, spec.ID, "d1"), "rollbackTarget")
110			})
111			assertReopenCorrupt(t, dir, original)
112		})
113	
114		// 设备已成功、活动已结束时目标丢失：活动结束也不取消这项要求。
115		t.Run("ended campaign without locked target", func(t *testing.T) {
116			s, spec := setupRollbackCampaign(t)
117			finishDevice(t, s, spec, "d1", upBase)
118			if v := mustGetCampaign(s, spec.ID); !v.Ended || v.Status != CampaignSucceeded {
119				t.Fatalf("precondition: %+v", v)
120			}
121			dir := closeStore(t, s)
122			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
123				delete(campaignDeviceDoc(doc, spec.ID, "d1"), "rollbackTarget")
124			})
125			assertReopenCorrupt(t, dir, original)
126		})
127	
128		// 同一存储里还有其他合法活动与设备时，仍必须整体拒绝打开，
129		// 不能只删掉损坏的设备或活动、让其余记录照常可用。
130		t.Run("whole store rejected alongside valid records", func(t *testing.T) {
131			s, spec := setupRollbackCampaign(t)
132			mustRegister(t, s, "d2", "v1")
133			other := upSpec()
134			other.ID = "cmp-2"
135			other.Devices = []string{"d2"}
136			other.BatchSize = 1
137			createCampaign(t, s, other)
138			if _, err := s.Claim(spec.ID, "d1", upBase); err != nil {
139				t.Fatalf("claim download: %v", err)
140			}
141			dir := closeStore(t, s)
142			original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
143				delete(campaignDeviceDoc(doc, spec.ID, "d1"), "rollbackTarget")
144			})
145			assertReopenCorrupt(t, dir, original)
146		})
147	}
148	
149	// TestRestoreRollbackTargetLegitStatesReopen 保护允许没有回滚目标的正常记录：
150	// 尚未领取下载的设备、首次领取前复查版本不兼容而直接在下载阶段失败的设备，
151	// 以及目标已正常锁定的记录（即使锁定版本没有单独登记为升级目标、设备影子
152	// 版本此后已被普通上报改变）都必须照常打开，回滚待办仍指向原先锁定的版本。
153	func TestRestoreRollbackTargetLegitStatesReopen(t *testing.T) {
154		// 新活动中的设备还没领取下载，可以没有回滚目标。
155		t.Run("pending device without target", func(t *testing.T) {
156			s, spec := setupRollbackCampaign(t)
157			dir := closeStore(t, s)
158			s2, err := Open(dir)
159			if err != nil {
160				t.Fatalf("reopen: %v", err)
161			}
162			defer s2.Close()
163			if d := findDevice(mustGetCampaign(s2, spec.ID), "d1"); d.Status != DevicePending ||
164				d.RollbackTarget != "" {
165				t.Fatalf("pending device after reopen: %+v", d)
166			}
167		})
168	
169		// 首次领取前复查版本不兼容、直接在下载阶段失败的设备允许没有目标：
170		// 这种失败不进入安装或回滚，不能只因记录中已有下载领取信息就拒绝打开。
171		t.Run("incompatible download failure without target", func(t *testing.T) {
172			s, spec := setupRollbackCampaign(t)
173			// 领取前通过普通上报把版本改为不兼容的 v9。
174			if err := s.Report("d1", 2, upBase.Add(-time.Minute), "v9", json.RawMessage(`{}`)); err != nil {
175				t.Fatalf("report: %v", err)
176			}
177			_, err := s.Claim(spec.ID, "d1", upBase)
178			if !errors.Is(err, ErrIncompatibleVersion) {
179				t.Fatalf("claim must fail incompatible: %v", err)
180			}
181			d := findDevice(mustGetCampaign(s, spec.ID), "d1")
182			if d.Status != DeviceFailed || d.Phase != StageDownload || d.RollbackTarget != "" {
183				t.Fatalf("precondition: %+v", d)
184			}
185			dir := closeStore(t, s)
186			s2, err := Open(dir)
187			if err != nil {
188				t.Fatalf("reopen: %v", err)
189			}
190			defer s2.Close()
191			d = findDevice(mustGetCampaign(s2, spec.ID), "d1")
192			if d.Status != DeviceFailed || d.Phase != StageDownload || d.RollbackTarget != "" {
193				t.Fatalf("failed device after reopen: %+v", d)
194			}
195		})
196	
197		// 锁定目标代表首次领取下载时的设备版本：下载后普通上报把影子版本改为
198		// v9，锁定的 v1 不变；v1 并未单独登记为升级目标，记录仍须原样打开，
199		// 安装失败后的回滚待办仍指向 v1，不能用当前影子版本或活动目标替代。
200		t.Run("locked target kept despite later version change", func(t *testing.T) {
201			s, spec := setupRollbackCampaign(t)
202			dl, err := s.Claim(spec.ID, "d1", upBase)
203			if err != nil {
204				t.Fatalf("claim download: %v", err)
205			}
206			// 下载已领取、目标已锁定为 v1；此后普通上报只改影子，不改锁定目标。
207			if err := s.Report("d1", 2, upBase.Add(30*time.Second), "v9", json.RawMessage(`{}`)); err != nil {
208				t.Fatalf("report: %v", err)
209			}
210			if err := s.SubmitResult(OperationResult{
211				CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
212				At: upBase.Add(time.Minute), Success: true,
213			}); err != nil {
214				t.Fatalf("download result: %v", err)
215			}
216			in, err := s.Claim(spec.ID, "d1", upBase.Add(2*time.Minute))
217			if err != nil {
218				t.Fatalf("claim install: %v", err)
219			}
220			if err := s.SubmitResult(OperationResult{
221				CampaignID: spec.ID, DeviceID: "d1", OperationID: in.ID,
222				At: upBase.Add(3 * time.Minute), Success: false, Reason: "install broken",
223			}); err != nil {
224				t.Fatalf("install failure: %v", err)
225			}
226			if sh, _ := s.Get("d1"); sh.Version != "v9" {
227				t.Fatalf("precondition: shadow version %s", sh.Version)
228			}
229			dir := closeStore(t, s)
230	
231			s2, err := Open(dir)
232			if err != nil {
233				t.Fatalf("reopen: %v", err)
234			}
235			defer s2.Close()
236			d := findDevice(mustGetCampaign(s2, spec.ID), "d1")
237			if d.Status != DeviceAwaitingRollback || d.RollbackTarget != "v1" {
238				t.Fatalf("awaiting rollback after reopen: %+v", d)
239			}
240			w, err := s2.GetDeviceWork("d1")
241			if err != nil {
242				t.Fatal(err)
243			}
244			if w.Pending == nil || w.Pending.Kind != StageRollback || w.Pending.TargetVersion != "v1" {
245				t.Fatalf("rollback todo must point at locked target: %+v", w)
246			}
247			if sh, _ := s2.Get("d1"); sh.Version != "v9" {
248				t.Fatalf("shadow version after reopen: %s", sh.Version)
249			}
250		})
251	}
