			d.RollbackTarget != "" {
			t.Fatalf("pending device after reopen: %+v", d)
		}
	})

	// 首次领取前复查版本不兼容、直接在下载阶段失败的设备允许没有目标：
	// 这种失败不进入安装或回滚，不能只因记录中已有下载领取信息就拒绝打开。
	t.Run("incompatible download failure without target", func(t *testing.T) {
