12	// 升级测试使用的时间线：
13	//
14	//	t0 12:00 创建活动；窗口 12:00–13:00（[start,end)）；截止 14:00。
15	var upBase = time.Date(2026, 10, 2, 12, 0, 0, 0, time.UTC)
16	
17	func upSpec() CampaignSpec {
18		return CampaignSpec{
19			ID:            "cmp-1",
20			Operator:      "alice",
21			CreatedAt:     upBase,
22			TargetVersion: "v2",
23			Devices:       nil,
24			BatchSize:     2,
25			WindowStart:   upBase,
26			WindowEnd:     upBase.Add(time.Hour),
27			Deadline:      upBase.Add(2 * time.Hour),
28		}
