31	// setupUpgrade 登记目标版本 v2（允许 v1）并登记若干 v1 设备。
32	func setupUpgrade(t *testing.T, devices ...string) *Store {
33		t.Helper()
34		s, _ := openTemp(t)
35		if err := s.RegisterUpgrade("v2", []string{"v1"}); err != nil {
36			t.Fatalf("RegisterUpgrade: %v", err)
37		}
38		for _, id := range devices {
39			mustRegister(t, s, id, "v1")
40		}
41		return s
42	}
43	
44	// bringOnline 用一次更大序号的上报把设备置为在线（版本 v1）。
45	func bringOnline(t *testing.T, s *Store, id string) {
46		t.Helper()
47		v, err := s.Get(id)
48		if err != nil {
49			t.Fatalf("Get %s: %v", id, err)
50		}
51		at := upBase.Add(time.Duration(v.LastSeq) * time.Minute).Add(-time.Minute)
52		if err := s.Report(id, v.LastSeq+1, at, "v1", json.RawMessage(`{}`)); err != nil {
53			t.Fatalf("Report %s: %v", id, err)
54		}
55	}
56	
57	func createCampaign(t *testing.T, s *Store, spec CampaignSpec) {
58		t.Helper()
59		if err := s.CreateCampaign(spec); err != nil {
60			t.Fatalf("CreateCampaign: %v", err)
61		}
62	}
63	
64	// finishDevice 完成一台设备的下载与安装，附带版本为 target 的上报（seq 2）。
65	func finishDevice(t *testing.T, s *Store, spec CampaignSpec, id string, at time.Time) {
66		t.Helper()
67		dl, err := s.Claim(spec.ID, id, at)
68		if err != nil {
